10	// ErrNoSuchInvoice is returned when an invoice id does not resolve.
11	var ErrNoSuchInvoice = errors.New("billing: no such invoice")
12	
13	// Charger settles invoices against a payment provider.
14	type Charger struct {
15		provider Provider
16		clock    func() time.Time
17		retries  int
18	}
19	
20	// NewCharger builds a Charger with a bounded retry budget.
21	func NewCharger(p Provider, retries int) *Charger {
22		return &Charger{provider: p, clock: time.Now, retries: retries}
23	}
24	
25	// Settle charges the invoice and records the attempt.
26	func (c *Charger) Settle(ctx context.Context, id string) (*Receipt, error) {
27		inv, err := c.provider.Lookup(ctx, id)
28		if err != nil {
29			return nil, fmt.Errorf("lookup %s: %w", id, err)
30		}
31		if inv == nil {
32			return nil, ErrNoSuchInvoice
33		}
34		for attempt := 0; attempt <= c.retries; attempt++ {
35			receipt, err := c.provider.Charge(ctx, inv)
36			if err == nil {
37				return receipt, nil
38			}
39			if !isRetryable(err) {
40				return nil, fmt.Errorf("charge %s: %w", id, err)
41			}
42		}
43		return nil, fmt.Errorf("charge %s: retries exhausted", id)
44	}

